__author__ = 'Marcin Siedlarz'


class PdmlParserError(Exception):
    pass


class MsgNotRecognized(PdmlParserError):
    def __init__(self, err_msg, packet, lte_msgs):
        super(MsgNotRecognized, self).__init__(err_msg)
        self.packet = packet
        self.lte_msgs = lte_msgs

    def __str__(self):
        err_msg = self.packet + '\n' \
                                'Packet has not been decoded correctly.\n ' \
                                'If packet that cannot be decoded is not needed in your verification,' \
                                ' try to filter it out by tshark read filters\n ' \
                                'If corrupted packet should be decoded or new feature is needed,' \
                                ' please contact Dawid Krawczuk (dawid.krawczuk@nokia.com)\n ' \
                                'supported lte msgs: %s\n' % self.lte_msgs + repr(self)
        return err_msg


class UesimConverterError(PdmlParserError):
    pass


class AsnParserError(PdmlParserError):
    pass
